package br.com.confirmacao.audit.api;import br.com.confirmacao.audit.domain.*;import java.time.Instant;import java.util.UUID;public record AuditLogResponse(UUID id,UUID actorUserId,AuditAction action,String resourceType,UUID resourceId,String ipAddress,Instant createdAt){public static AuditLogResponse from(AuditLog l){return new AuditLogResponse(l.getId(),l.getActorUserId(),l.getAction(),l.getResourceType(),l.getResourceId(),l.getIpAddress(),l.getCreatedAt());}}
